import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
const lane = '/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes/history-only-reword-6qjyzwas/tree';
const parent = '/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes';
const root = mkdtempSync(join(parent, 'catalog-provenance-actual-'));
const commands = [];
function run(args, cwd = root) {
  const result = spawnSync(args[0], args.slice(1), { cwd, encoding: 'utf8', env: { ...process.env, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1', GIT_AUTHOR_DATE: '2026-01-01T00:00:00Z', GIT_COMMITTER_DATE: '2026-01-01T00:00:00Z' } });
  const receipt = { args, exitCode: result.status, stdout: result.stdout ?? '', stderr: result.stderr ?? '' };
  commands.push(receipt);
  return receipt;
}
function git(...args) { const result = run(['git', ...args]); assert.equal(result.exitCode, 0, result.stderr); return result.stdout.trim(); }
function skill(path, description) { mkdirSync(join(root, path), { recursive: true }); writeFileSync(join(root, path, 'SKILL.md'), `---\ndescription: ${JSON.stringify(description)}\n---\n`); }
function commit(message) { git('add', '-A'); git('commit', '-qm', message); return git('rev-parse', 'HEAD'); }
function cli(...args) { return run(['bun', join(root, 'scripts/legacy-skills-catalog.ts'), ...args]); }
try {
  git('init', '-q', '-b', 'main');
  git('config', 'user.name', 'Local provenance fixture'); git('config', 'user.email', 'fixture@example.invalid');
  git('config', 'commit.gpgsign', 'false');
  mkdirSync(join(root, 'scripts'), { recursive: true }); mkdirSync(join(root, 'src/lib'), { recursive: true });
  for (const file of ['git-history-ownership.ts', 'legacy-skills-catalog.ts']) copyFileSync(join(lane, 'scripts', file), join(root, 'scripts', file));
  for (const file of ['legacy-skills.ts', 'skills-agents.ts']) copyFileSync(join(lane, 'src/lib', file), join(root, 'src/lib', file));
  writeFileSync(join(root, 'src/lib/legacy-skills-catalog.ts'), 'export const LEGACY_MARKER_DIRS=[]; export const LEGACY_SKILL_NAMES=["recorded-only"]; export const LEGACY_SKILL_DESCRIPTIONS=["Recorded independent Genie proof."];\n');
  skill('skills/demo', 'Current Genre fixture skill.'); skill('skills/genie-shared', 'Unrecorded shared Genre retirement proof.');
  const shared = commit('seed Genre delivery');
  rmSync(join(root, 'skills/genie-shared'), { recursive: true }); const genie = commit('retire shared Genre skill');
  skill('skills/genie-archive', 'Unrecorded archived Genre retirement proof.'); git('add', '-A');
