      ['refs/remotes/origin/unmerged-feature', 'unmerged-feature', 'Never shipped unmerged Genre PR skill.'],
      ['refs/remotes/origin/dev-experiment', 'dev-lookalike', 'Lookalike dev branch is not shipped.'],
      ['refs/heads/trusted-archive', 'archive-outside', 'Unrecorded trusted Genre archive beyond shipped defaults.'],
