  skill('skills/genie-source-only', 'Source-only historical description must never grant retirement authority.');
  git('add', '-A'); const foreign = git('commit-tree', git('write-tree'), '-p', archive, '-m', 'independent source delivery');
  git('update-ref', 'refs/tags/history', foreign);
