  git('update-ref', 'refs/heads/main', imported); git('update-ref', 'refs/heads/source', split);
  const noProof = cli(); assert.equal(noProof.exitCode, 1); assert.match(noProof.stderr, /ambiguous history reference/); assert.equal(noProof.stdout, '');
  const selector = `${authority}:ref-proof.json`;
  const rendered = cli('--ref-provenance', selector); assert.equal(rendered.exitCode, 0, rendered.stderr); assert.equal(rendered.stderr, '');
