  writeFileSync(join(root, 'src/lib/legacy-skills-catalog.ts'), rendered.stdout);
  const agent = join(root, 'isolated-agent-skills');
  for (const [name, description] of [['genie-shared', 'Unrecorded shared Genre retirement proof.'], ['genie-archive', 'Unrecorded archived Genre retirement proof.'], ['genie-source-only', 'Source-only historical description must never grant retirement authority.']]) skill(`isolated-agent-skills/${name}`, description);
