  assert.equal(classification.exitCode, 0, classification.stderr);
  const classified = JSON.parse(classification.stdout); assert.equal(classified['genie-shared'], 'proven'); assert.equal(classified['genie-archive'], 'proven'); assert.equal(classified['genie-source-only'], 'unproven');
  git('update-ref', 'refs/tags/history', side); const stale = cli('--ref-provenance', selector); assert.equal(stale.exitCode, 1); assert.match(stale.stderr, /stale or unknown reference provenance/); assert.equal(stale.stdout, '');
  const hashes = Object.fromEntries(['scripts/git-history-ownership.ts','scripts/legacy-skills-catalog.ts','src/lib/legacy-skills.ts','src/lib/skills-agents.ts'].map(path=>[path,createHash('sha256').update(readFileSync(join(root,path))).digest('hex')]));
